// Règles qui donnent une couche à un chemin (la première qui correspond gagne)
const layerRules = [
  [/__tests__\//, 'test'],
  [/^src\/app\//, 'ecran'],
  [/^src\/components\//, 'composant'],
  [/^src\/features\/.*\.tsx$/, 'composant'],
  [/^src\/features\/mascot\/(mascot-visuals|mascot-bubble-layout|onboarding-guide-state)\.ts$/, 'apparence'],
  [/^src\/features\/launch\/splash-constants\.ts$/, 'apparence'],
  [/^src\/features\//, 'composant'],
  [/^src\/(styles|constants)\//, 'apparence'],
  [/^src\/hooks\//, 'apparence'],
  [/^src\/global\.css$/, 'apparence'],
  [/^src\/domain\//, 'regle'],
  [/^src\/use-cases\//, 'usecase'],
  [/^src\/repositories\//, 'depot'],
  [/^src\/database\//, 'base'],
  [/^src\/(services|background|widget)\//, 'service'],
  [/^src\/store\//, 'etat'],
  [/^src\/i18n\//, 'i18n'],
  [/^src\/utils\//, 'regle'],
  [/^docs\//, 'doc'],
  [/^assets\//, 'ressource'],
  [/^(node_modules|android|\.expo|dist|\.claude)\//, 'genere'],
  [/^(\.env|expo-env\.d\.ts)$/, 'genere'],
  [/\.md$/, 'doc'],
  [/^LICENSE$/, 'doc'],
  [/.*/, 'config'],
];

